package com.beez.backend.document.service;

import static org.assertj.core.api.Assertions.*;

import com.beez.backend.common.api.ApiException;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.json.JsonMapper;

/** The fixture is generated by AI's document-chunks-v1 implementation with a character counter. */
class DocumentChunkValidatorTest {
    private static final JsonMapper JSON = JsonMapper.builder().build();

    @SuppressWarnings("unchecked")
    private Map<String, Object> fixture() {
        return JSON.readValue(getClass().getResourceAsStream("/document-chunks-223.json"), Map.class);
    }
    @SuppressWarnings("unchecked")
    private Map<String, Object> plainFixture() {
        return JSON.readValue(getClass().getResourceAsStream("/document-chunks-plain-223.json"), Map.class);
    }
    @SuppressWarnings("unchecked") private static Map<String, Object> map(Object value) { return (Map<String, Object>) value; }
    @SuppressWarnings("unchecked") private static List<Object> list(Object value) { return (List<Object>) value; }
    private static Map<String, Object> result(Map<String, Object> fixture) { return map(map(fixture.get("response")).get("result")); }
    private static List<Map<String, Object>> validate(Map<String, Object> fixture) {
        var input = map(fixture.get("input"));
        return DocumentChunkValidator.validate((String) input.get("content"), input, result(fixture));
    }

    @Test void acceptsActualAiUnicodeLongLineMultipleSpansAndExcludedRanges() {
        var fixture = fixture();
        var chunks = validate(fixture);
        assertThat(chunks).hasSize(4);
        assertThat(chunks.stream().map(c -> list(c.get("source_spans")).size())).anyMatch(n -> n > 1);
        assertThat(list(result(fixture).get("excluded_ranges"))).isNotEmpty();
        assertThat(chunks.stream().flatMap(c -> list(c.get("source_spans")).stream())
                .map(DocumentChunkValidatorTest::map)
                .filter(s -> map(s.get("locator")).get("start_line").equals(8)).count()).isGreaterThan(1);
    }

    @Test void rejectsWrongManifestAndKeySet() {
        var wrongHash = fixture();
        map(result(wrongHash).get("manifest")).put("text_hash", "0".repeat(64));
        assertThatThrownBy(() -> validate(wrongHash)).isInstanceOf(ApiException.class);
        var wrongKeys = fixture();
        list(map(result(wrongKeys).get("manifest")).get("expected_chunk_keys")).set(0, "other");
        assertThatThrownBy(() -> validate(wrongKeys)).isInstanceOf(ApiException.class);
    }

    @Test void rejectsMislocatedOverlappingAndMissingSource() {
        var wrongLocator = fixture();
        var firstChunk = map(list(result(wrongLocator).get("chunks")).getFirst());
        var firstSpan = map(list(firstChunk.get("source_spans")).getFirst());
        map(firstSpan.get("locator")).put("start_line", 2);
        assertThatThrownBy(() -> validate(wrongLocator)).isInstanceOf(ApiException.class);

        var overlap = fixture();
        var secondChunk = map(list(result(overlap).get("chunks")).get(1));
        var secondSpan = map(list(secondChunk.get("source_spans")).getFirst());
        secondSpan.put("start_offset", 0);
        assertThatThrownBy(() -> validate(overlap)).isInstanceOf(ApiException.class);

        var missing = fixture();
        list(result(missing).get("excluded_ranges")).removeFirst();
        assertThatThrownBy(() -> validate(missing)).isInstanceOf(ApiException.class);
    }

    @Test void rejectsChangedSourceTextAndForgedExclusion() {
        var text = fixture();
        map(list(result(text).get("chunks")).getFirst()).put("text", "다른 원문");
        assertThatThrownBy(() -> validate(text)).isInstanceOf(ApiException.class);
        var exclusion = fixture();
        map(list(result(exclusion).get("excluded_ranges")).getFirst()).put("reason", "thematic_break");
        assertThatThrownBy(() -> validate(exclusion)).isInstanceOf(ApiException.class);
    }

    @Test void rejectsChangesToFixedProfileOrEmbeddingContent() {
        for (var change : Map.<String, Object>of("max_tokens", 601, "max_chunks", 1023,
                "include_headings", true, "include_table_headers", true).entrySet()) {
            var altered = fixture();
            map(map(result(altered).get("manifest")).get("chunking_profile")).put(change.getKey(), change.getValue());
            assertThatThrownBy(() -> validate(altered)).isInstanceOf(ApiException.class);
        }
        var wrongEmbedding = fixture();
        map(list(result(wrongEmbedding).get("chunks")).getFirst()).put("embedding_text", "unverified context");
        assertThatThrownBy(() -> validate(wrongEmbedding)).isInstanceOf(ApiException.class);
        var applied = fixture();
        var firstChunk = map(list(result(applied).get("chunks")).getFirst());
        map(list(firstChunk.get("context_refs")).getFirst()).put("applied", true);
        assertThatThrownBy(() -> validate(applied)).isInstanceOf(ApiException.class);
        var roleless = fixture();
        map(list(map(list(result(roleless).get("chunks")).getFirst()).get("context_refs")).getFirst()).remove("role");
        assertThatThrownBy(() -> validate(roleless)).isInstanceOf(ApiException.class);
    }

    @Test void parserProfileMustMatchTheRequestedMediaType() {
        var plain = plainFixture();
        assertThat(validate(plain)).hasSize(1);
        map(result(plain).get("manifest")).put("parser_profile", "markdown-v1");
        assertThatThrownBy(() -> validate(plain)).isInstanceOf(ApiException.class);
        var markdown = fixture();
        map(result(markdown).get("manifest")).put("parser_profile", "plain-v1");
        assertThatThrownBy(() -> validate(markdown)).isInstanceOf(ApiException.class);
    }

    @Test void plainTextRejectsMarkdownExcludedRanges() {
        for (var exclusion : Map.of("thematic_break", "---", "container_marker", ">  ").entrySet()) {
            var plain = fixture();
            var input = map(plain.get("input"));
            input.put("content", ((String) input.get("content")).replace("---", exclusion.getValue()));
            var ranges = list(result(plain).get("excluded_ranges"));
            var marker = ranges.stream().map(DocumentChunkValidatorTest::map)
                    .filter(range -> "thematic_break".equals(range.get("reason"))).findFirst().orElseThrow();
            marker.put("reason", exclusion.getKey());
            assertThat(validate(plain)).hasSize(4);
            input.put("media_type", "text/plain");
            map(result(plain).get("manifest")).put("parser_profile", "plain-v1");
            assertThatThrownBy(() -> validate(plain)).isInstanceOf(ApiException.class)
                    .hasMessage("invalid_excluded_range");
        }
    }

    @Test void embeddingRequestMapsEmbeddingTextField() {
        // Mapping is tested independently with distinct values: valid v1 responses have identical fields.
        var chunks = List.of(Map.<String, Object>of("chunk_key", "key", "text", "source", "embedding_text", "embedding"));
        assertThat(DocumentIndexWorker.embeddingTexts(chunks)).containsExactly(Map.of("key", "key", "text", "embedding"));
    }

    @Test void handlesLongExcludedMarkersWithoutRegexRecursion() {
        assertThat(DocumentChunkValidator.validExcludedLine(">".repeat(90_000) + " -\n", "container_marker")).isTrue();
        assertThat(DocumentChunkValidator.validExcludedLine(">".repeat(90_000) + " content\n", "container_marker")).isFalse();
        assertThat(DocumentChunkValidator.validExcludedLine(" ".repeat(90_000) + "\n", "blank")).isTrue();
        assertThat(DocumentChunkValidator.validExcludedLine(">".repeat(90_000) + " ---\n", "thematic_break")).isTrue();
        assertThat(DocumentChunkValidator.validExcludedLine("* ".repeat(45_000) + "+\n", "thematic_break")).isFalse();
        assertThat(DocumentChunkValidator.validExcludedLine("* ".repeat(45_000) + "+ ---\n", "thematic_break")).isTrue();
        assertThat(DocumentChunkValidator.validExcludedLine("> 1. - * * *\n", "thematic_break")).isTrue();
        assertThat(DocumentChunkValidator.validExcludedLine("> 1.-***\n", "thematic_break")).isFalse();
    }
}
